const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createRequire}=require('node:module');
const root=path.resolve(__dirname,'../../..'),r=createRequire(root+'/apps/api/package.json'),ts=r('typescript');let cursor=0,slots=[],effects=[],timer,submission,redirects=[],calls=0,resolve,reject;const toasts=[];
const react={useRef(value){const i=cursor++;return slots[i]??=( {current:value})},useState(value){const i=cursor++;if(!(i in slots))slots[i]=value;return[slots[i],value=>slots[i]=value]},useEffect(callback){cursor++;effects.push(callback)}};
