 function req(name){if(name==='react')return react;if(name==='react/jsx-runtime')return{jsx,jsxs:jsx};if(name==='react-hook-form')return{useForm:()=>({handleSubmit:callback=>callback,control:{}})};if(name==='react-hot-toast')return{toast:Object.fromEntries(['loading','success','error'].map(kind=>[kind,(message)=>{toasts.push({kind,message});return'fixture-toast'}]))};
  if(name==='next/router')return{useRouter:()=>({push:url=>redirects.push(url)})};if(name==='../api/query')return{authQuery:{register:{useMutation:()=>({mutateAsync(){calls++;return new Promise((a,b)=>{resolve=a;reject=b})}})}}};if(name==='../api/server')return{};if(name==='../api/registration-feedback')return load('apps/web/src/api/registration-feedback.ts');if(name.endsWith('.png'))return{};return new Proxy({},{get:(_target,key)=>String(key)})}
